package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen2Test {

    @Test
    public void testConstructorAndReadSingleByte() throws IOException {
        byte[] data = new byte[]{1, 2, 3};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        try (ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in)) {
            assertEquals(1, cis.read());
            assertEquals(2, cis.read());
            assertEquals(3, cis.read());
            assertEquals(-1, cis.read());

            assertEquals(crc32.getValue(), cis.getValue());
        }
    }










}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen2Test {



    @Test
    public void testReadByteArray() throws IOException {
        byte[] data = "Hello World".getBytes();
        CRC32 crc32 = new CRC32();
        crc32.update(data);
        InputStream in = new ByteArrayInputStream(data);

        try (ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in)) {
            byte[] buffer = new byte[5];
            int read = cis.read(buffer);
            assertEquals(5, read);
            assertEquals("Hello", new String(buffer));

            read = cis.read(buffer, 0, 2);
            assertEquals(2, read);
            assertEquals((byte) ' ', buffer[0]);
            assertEquals((byte) 'W', buffer[1]);

            assertEquals(crc32.getValue(), cis.getValue());
        }
    }








}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen2Test {





    @Test
    public void testSkip() throws IOException {
        byte[] data = new byte[]{10, 20, 30, 40, 50};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        try (ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in)) {
            long skipped = cis.skip(2);
            assertEquals(2L, skipped);

            assertEquals(30, cis.read());
            assertEquals(crc32.getValue(), cis.getValue());
        }
    }






}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
